-- VERIFY (read-only): expect total 3732, evo_rows 706, new_weapon_rows 132, armor_break_null_on_evo 706, upper_limb_stk_null 49 (37 updated + 12 new).
SELECT count(*) AS total,
  count(*) FILTER (WHERE verified_source LIKE 'Evo4Fun in-game testing workbook (EVA WARDOGS)%') AS evo_rows,
  count(*) FILTER (WHERE weapon_name IN ('TCX-SPR', 'PP-19 Bizon', 'M14', 'Evo-3 Ultra')) AS new_weapon_rows,
  count(*) FILTER (WHERE verified_source LIKE 'Evo4Fun in-game testing workbook (EVA WARDOGS)%' AND armor_break_shots IS NULL) AS armor_break_null_on_evo,
  count(*) FILTER (WHERE verified_source LIKE 'Evo4Fun in-game testing workbook (EVA WARDOGS)%' AND body_part = 'UPPER LIMB' AND shots_to_kill IS NULL) AS upper_limb_stk_null
FROM wardogs_ballistics WHERE game_slug = 'wardogs';
